# qx2_uuid3 :: ('_', 'example.com')
import uuid

def qx2_uuid3(name, ns='example.com'):
    return str(uuid.uuid3(uuid.NAMESPACE_DNS, ns + '/' + name))

if __name__ == '__main__':
    print(qx2_uuid3(*('_', 'example.com')))

